// 测试用的 obsidian 替身：requestUrl 走真实网络（live 测试）或被 check.cjs 覆盖
class Base { constructor(app){ this.app = app; } }
module.exports = {
  Plugin: Base, Modal: Base, PluginSettingTab: Base, Setting: Base, FuzzySuggestModal: Base,
  ItemView: Base, BasesView: Base, MarkdownView: Base, Menu: Base, Platform: {}, setIcon: () => {},
  debounce: (fn) => fn, normalizePath: (p) => p.replace(/\/+/g, "/").replace(/^\/|\/$/g, "") || "/",
  Notice: class { hide(){} }, TFile: class {}, TFolder: class {},
  getLanguage: () => "zh", getAllTags: () => [],
  requestUrl: async (r) => {
    const res = await fetch(r.url, { method: r.method, headers: r.headers, body: r.body });
    const text = await res.text();
    return { status: res.status, text, get json() { return JSON.parse(text); } };
  },
};
